import React, { useEffect, useRef, useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import LinearGradient from 'react-native-linear-gradient';

import { categoryConfig } from './categoryConfig';
import { spacing } from '../../theme';
import { fontFamily } from '../../constants/fonts';
import { translateUiText } from '../../i18n/uiTranslation';

const FORMAT_FALLBACKS = {
    wouldyourather: ['Option A', 'Option B'],
    thisorthat: ['This', 'That'],
};

const normalizeOption = option => (
    option && typeof option === 'object'
        ? { value: option.value, label: option.label ?? option.value }
        : { value: option, label: option }
);

const ChoiceQuestionCard = React.memo(({
    task,
    index,
    displayIndex,
    totalCards,
    hasPartner = false,
    onLinkPartner,
    onSubmit,
    onAnswerSubmit,
    isAnswered = false,
    previousAnswer = null,
    autoAdvanceOnSubmit = true,
    isLocked = false,
    onNavigateToPremium = () => { },
}) => {
    const config = categoryConfig[task.category] || categoryConfig.deep;
    const rawOptions = task.optionItems?.length > 0
        ? task.optionItems
        : (task.options?.length > 0 ? task.options : FORMAT_FALLBACKS[task.category] || ['Yes', 'No']);
    const options = rawOptions.map(normalizeOption);
    const [selectedAnswer, setSelectedAnswer] = useState(isAnswered ? previousAnswer : null);
    const [locked, setLocked] = useState(isAnswered);
    const lastTaskIdRef = useRef(task._id);

    useEffect(() => {
        if (lastTaskIdRef.current !== task._id) {
            lastTaskIdRef.current = task._id;
            setSelectedAnswer(isAnswered ? previousAnswer : null);
            setLocked(isAnswered);
        }
    }, [task._id, isAnswered, previousAnswer]);

    const handleSelect = async ({ value }) => {
        if (locked || isAnswered) return;
        if (isLocked) {
            onNavigateToPremium?.();
            return;
        }
        if (!hasPartner) {
            onLinkPartner?.();
            return;
        }

        setSelectedAnswer(value);
        setLocked(true);

        try {
            const submitted = await onAnswerSubmit?.(task.originalIndex ?? index, value, 'choice');
            if (submitted === false) {
                setSelectedAnswer(null);
                setLocked(false);
                return;
            }

            if (autoAdvanceOnSubmit && onSubmit) {
                onSubmit(value);
            }
        } catch (err) {
            console.error('handleSelect error:', err);
            setSelectedAnswer(null);
            setLocked(false);
        }
    };

    return (
        <LinearGradient colors={['#FF758F', '#C2185B']} style={styles.cardContainer}>
            <View style={styles.cardContent}>
                <View style={styles.topRow}>
                    <View style={styles.categoryBadge}>
                        <Text style={styles.badgeEmoji}>{config.emoji || '💬'}</Text>
                        <Text style={styles.categoryText}>{translateUiText(config.label)}</Text>
                    </View>
                </View>

                <View style={styles.questionSection}>
                    <Text style={styles.questionText}>{task.taskstatement}</Text>
                </View>

                <View style={styles.choicesColumn}>
                    {options.map((choice) => (
                        <TouchableOpacity
                            key={String(choice.value)}
                            style={[
                                styles.choiceButton,
                                selectedAnswer === choice.value && styles.choiceSelected,
                            ]}
                            onPress={() => handleSelect(choice)}
                            disabled={locked || isAnswered}
                            activeOpacity={0.85}
                        >
                            <Text style={[
                                styles.choiceLabel,
                                selectedAnswer === choice.value && styles.choiceLabelSelected,
                            ]}>
                                {translateUiText(choice.label)}
                            </Text>
                        </TouchableOpacity>
                    ))}
                </View>

            </View>
        </LinearGradient>
    );
});

const styles = StyleSheet.create({
    cardContainer: {
        flex: 1,
        borderRadius: 28,
        overflow: 'hidden',
        borderWidth: 6,
        borderColor: 'rgba(255, 255, 255, 0.20)',
    },
    cardContent: {
        flex: 1,
        paddingHorizontal: spacing.lg,
        paddingTop: spacing.lg,
        paddingBottom: spacing.md,
    },
    topRow: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: spacing.md,
    },
    categoryBadge: {
        backgroundColor: 'rgba(255,255,255,0.12)',
        flexDirection: 'row',
        alignItems: 'center',
        gap: 6,
        paddingVertical: 9,
        paddingHorizontal: 16,
        borderRadius: 20,
        borderWidth: 1,
        borderColor: 'rgba(255,255,255,0.22)',
    },
    badgeEmoji: {
        fontSize: 16,
    },
    categoryText: {
        color: '#FFFFFF',
        fontSize: 13,
        fontWeight: '800',
        fontFamily: fontFamily.bold,
    },
    counterText: {
        fontSize: 14,
        fontWeight: '800',
        color: 'rgba(255, 255, 255, 0.75)',
        fontFamily: fontFamily.bold,
    },
    questionSection: {
        flex: 1,
        justifyContent: 'center',
        paddingHorizontal: spacing.sm,
    },
    questionText: {
        fontSize: 24,
        fontWeight: '800',
        color: '#FFFFFF',
        lineHeight: 30,
        textAlign: 'center',
        fontFamily: fontFamily.extraBold,
    },
    choicesColumn: {
        width: '90%',
        alignSelf: 'center',
        alignItems: 'stretch',
        gap: spacing.sm,
        marginBottom: spacing.md,
    },
    choiceButton: {
        width: '100%',
        alignSelf: 'center',
        minHeight: 52,
        borderRadius: 20,
        backgroundColor: 'rgba(255, 255, 255, 0.12)',
        borderWidth: 1.5,
        borderColor: 'rgba(255, 255, 255, 0.22)',
        justifyContent: 'center',
        alignItems: 'center',
        paddingHorizontal: spacing.md,
    },
    choiceSelected: {
        backgroundColor: '#FFFFFF',
        borderColor: '#FFFFFF',
        borderWidth: 2.5,
    },
    choiceLabel: {
        color: '#FFFFFF',
        fontSize: 16,
        fontWeight: '800',
        textAlign: 'center',
        fontFamily: fontFamily.bold,
    },
    choiceLabelSelected: {
        color: '#C2185B',
    },
    hidden: {
        opacity: 0,
    },
});

export default ChoiceQuestionCard;
