import { NativeModules, Platform } from 'react-native';

const { WebRTCModule } = NativeModules;

export default class RTCAudioSession {
    /**
     * Route iOS WebRTC audio through the loudspeaker or the system default
     * receiver while holding WebRTC's own audio-session configuration lock.
     */
    static async setAudioOutput(speaker: boolean): Promise<{ route: string; speaker: boolean }> {
        if (Platform.OS !== 'ios') {
            return { route: 'unsupported', speaker: false };
        }

        return WebRTCModule.setAudioOutput(speaker);
    }

    /**
     * To be called when CallKit activates the audio session.
     */
    static audioSessionDidActivate() {
        // Only valid for iOS
        if (Platform.OS === 'ios') {
            WebRTCModule.audioSessionDidActivate();
        }
    }

    /**
     * To be called when CallKit deactivates the audio session.
     */
    static audioSessionDidDeactivate() {
        // Only valid for iOS
        if (Platform.OS === 'ios') {
            WebRTCModule.audioSessionDidDeactivate();
        }
    }
}
